func And(predicates ...predicate.MediaProvider) predicate.MediaProvider {
	return predicate.MediaProvider(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.MediaProvider) predicate.MediaProvider {
	return predicate.MediaProvider(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.MediaProvider) predicate.MediaProvider {
	return predicate.MediaProvider(sql.NotPredicates(p))
}
